fn main() {
    let threshold = 10;
    let is_big = |n: i32| n > threshold;   // reads threshold: borrows it
    println!("{} {}", is_big(5), is_big(15));

    let mut count = 0;
    let mut bump = || count += 1;           // changes count: borrows it mutably
    bump();
    bump();
    println!("count is {count}");
}

fn main() {
    let name = String::from("Ana");
    let greet = move || println!("hi {name}");
    greet();
    greet();
    // println!("{name}");  // would not compile: E0382, borrow of moved value
}

fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n
}

fn main() {
    let add_five = make_adder(5);
    let add_ten = make_adder(10);
    println!("{} {}", add_five(1), add_ten(1));
}

fn call_twice(f: impl Fn()) {
    f();
    f();
}

fn call_mut_twice(mut f: impl FnMut()) {
    f();
    f();
}

fn call_once(f: impl FnOnce() -> String) -> String {
    f()
}

fn main() {
    call_twice(|| println!("hello"));

    let mut total = 0;
    call_mut_twice(|| total += 5);
    println!("total {total}");

    let name = String::from("Ana");
    let reply = call_once(move || name);   // gives name away, so only once
    println!("{reply}");
}

