fn make_counter() -> impl FnMut() -> u32 {
    // return a closure that adds 1 to a counter of its own each time it is called,
    // and gives the counter back: 1, then 2, then 3, ...
    || 0
}

fn main() {
    let bonus = 5;
    let add_bonus = |score: i32| score + bonus;
    println!("{}", add_bonus(10));

    let mut counter = make_counter();
    counter();
    counter();
    println!("{}", counter());
}

